//! Real-engine integration tests.
//!
//! These start **two actual Xray-core processes** — a local server with a
//! VLESS inbound, and a client whose config is generated by `kvn-core`
//! from a share link — and verify that traffic flows end-to-end through
//! the generated config, that the stats API reports counters, and that the
//! engine's own config validation (`run -test`) rejects broken configs.
//!
//! ```text
//! XRAY_BIN=/path/to/xray cargo test -p kvn-engine --test xray_integration
//! ```
//!
//! Without `XRAY_BIN` every test reports "skipped" and passes, so CI
//! without an engine binary stays green — but on any machine with the
//! engine present these are real assertions, not mocks.

use std::path::{Path, PathBuf};
use std::time::Duration;

use kvn_core::uri::parse_uri;
use kvn_core::xray::{build_client_config, BuildOptions};
use kvn_engine::{
    check_through_socks, query_stats, spawn_engine, validate_config, wait_for_port, EngineProcess,
    HealthTarget, SpawnOptions,
};
use serde_json::json;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::TcpListener;

const TEST_UUID: &str = "11111111-2222-3333-4444-555555555555";
const READY_TIMEOUT: Duration = Duration::from_secs(10);
const CHECK_TIMEOUT: Duration = Duration::from_secs(10);

fn xray_bin() -> Option<PathBuf> {
    let path = std::env::var("XRAY_BIN").ok()?;
    let path = PathBuf::from(path);
    if path.exists() {
        Some(path)
    } else {
        panic!("XRAY_BIN is set to `{}` but does not exist", path.display());
    }
}

/// Kills the guard's process on drop so a failing assertion never leaks an
/// engine process.
struct KillGuard(Option<EngineProcess>);

impl Drop for KillGuard {
    fn drop(&mut self) {
        if let Some(process) = &mut self.0 {
            process.kill_now();
        }
    }
}

async fn free_port() -> u16 {
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    listener.local_addr().unwrap().port()
}

/// A minimal HTTP server answering 204 to anything; it plays the role of a
/// `generate_204` endpoint behind the tunnel.
async fn start_204_server() -> u16 {
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let port = listener.local_addr().unwrap().port();
    tokio::spawn(async move {
        loop {
            let Ok((mut socket, _)) = listener.accept().await else {
                break;
            };
            tokio::spawn(async move {
                let mut buf = [0u8; 2048];
                let _ = socket.read(&mut buf).await;
                let _ = socket
                    .write_all(b"HTTP/1.1 204 No Content\r\nConnection: close\r\n\r\n")
                    .await;
                let _ = socket.shutdown().await;
            });
        }
    });
    port
}

/// Server-side inbound for the VLESS variant under test.
fn server_config(
    inbound_port: u16,
    network: &str,
    extra_stream: serde_json::Value,
) -> serde_json::Value {
    let mut stream = json!({ "network": network, "security": "none" });
    if let Some(obj) = extra_stream.as_object() {
        for (key, value) in obj {
            stream[key] = value.clone();
        }
    }
    json!({
        "log": { "loglevel": "warning", "access": "none" },
        "inbounds": [{
            "listen": "127.0.0.1",
            "port": inbound_port,
            "protocol": "vless",
            "settings": {
                "clients": [{ "id": TEST_UUID, "level": 0 }],
                "decryption": "none"
            },
            "streamSettings": stream
        }],
        "outbounds": [{ "protocol": "freedom", "tag": "direct" }]
    })
}

async fn write_config(dir: &Path, name: &str, config: &serde_json::Value) -> PathBuf {
    let path = dir.join(name);
    std::fs::write(&path, serde_json::to_vec_pretty(config).unwrap()).unwrap();
    path
}

/// The full vertical slice: server up → client built from a share link →
/// engine-validated → started → real traffic through the tunnel → stats.
async fn run_variant(
    network: &str,
    type_param: &str,
    query_path: &str,
    server_stream: serde_json::Value,
) {
    let Some(bin) = xray_bin() else {
        eprintln!("XRAY_BIN not set: skipping real-engine test for `{network}`");
        return;
    };
    let dir = tempfile::tempdir().unwrap();

    let echo_port = start_204_server().await;
    let server_port = free_port().await;
    let server_cfg = write_config(
        dir.path(),
        "server.json",
        &server_config(server_port, network, server_stream),
    )
    .await;
    validate_config(&bin, &server_cfg)
        .await
        .expect("server config must validate");

    let server = spawn_engine(&SpawnOptions {
        binary: bin.clone(),
        config_path: server_cfg,
        stderr_log: Some(dir.path().join("server-stderr.log")),
        work_dir: None,
    })
    .await
    .expect("server engine must start");
    let mut server_guard = KillGuard(Some(server));
    wait_for_port(server_port, READY_TIMEOUT)
        .await
        .expect("server must listen");

    // Client profile exactly as it would arrive from the panel.
    let link = format!(
        "vless://{TEST_UUID}@127.0.0.1:{server_port}?type={type_param}&security=none{query_path}#it-{network}"
    );
    let profile = parse_uri(&link).expect("share link must parse");

    let socks_port = free_port().await;
    let http_port = free_port().await;
    let api_port = free_port().await;
    let outcome = build_client_config(
        &profile,
        &BuildOptions {
            socks_port,
            http_port,
            api_port,
            // LAN bypass would send the loopback probe around the tunnel.
            bypass_lan: false,
            ..Default::default()
        },
    )
    .expect("client config must build");

    let client_cfg = write_config(dir.path(), "client.json", &outcome.config).await;
    validate_config(&bin, &client_cfg)
        .await
        .expect("generated client config must be accepted by the engine");

    let client = spawn_engine(&SpawnOptions {
        binary: bin.clone(),
        config_path: client_cfg,
        stderr_log: Some(dir.path().join("client-stderr.log")),
        work_dir: None,
    })
    .await
    .expect("client engine must start");
    let mut client_guard = KillGuard(Some(client));
    wait_for_port(socks_port, READY_TIMEOUT)
        .await
        .expect("client socks port must listen");

    // Real traffic through the tunnel: SOCKS5 → server inbound → freedom →
    // our 204 endpoint on loopback.
    let latency = check_through_socks(
        socks_port,
        &HealthTarget {
            host: "127.0.0.1".to_owned(),
            http_path: "/".to_owned(),
            port: echo_port,
        },
        CHECK_TIMEOUT,
    )
    .await
    .unwrap_or_else(|e| panic!("traffic through `{network}` tunnel must work: {e}"));

    // Stats API answers; counters are updated asynchronously, so poll
    // briefly until the traffic we just generated is accounted for.
    let mut snapshot = kvn_engine::TrafficSnapshot::default();
    for _ in 0..15 {
        snapshot = query_stats(&bin, api_port, CHECK_TIMEOUT)
            .await
            .expect("stats query must succeed");
        if snapshot.total_bytes() > 0 {
            break;
        }
        tokio::time::sleep(Duration::from_millis(200)).await;
    }
    assert!(
        snapshot.total_bytes() > 0,
        "traffic counters must be non-zero after a successful check (latency {latency}ms); \
         ports socks={socks_port} http={http_port} api={api_port} server={server_port}: {snapshot:?}"
    );

    // Graceful stop; ports close afterwards.
    let client = client_guard.0.take().unwrap();
    client
        .stop(Duration::from_secs(5))
        .await
        .expect("client must stop");
    assert!(
        wait_for_port(socks_port, Duration::from_millis(800))
            .await
            .is_err(),
        "socks port must be closed after stop"
    );

    let server = server_guard.0.take().unwrap();
    server
        .stop(Duration::from_secs(5))
        .await
        .expect("server must stop");
}

#[tokio::test]
async fn vless_tcp_end_to_end() {
    run_variant("tcp", "tcp", "", json!({})).await;
}

#[tokio::test]
async fn vless_ws_end_to_end() {
    run_variant(
        "ws",
        "ws",
        "&path=%2Fit-ws",
        json!({ "wsSettings": { "path": "/it-ws" } }),
    )
    .await;
}

#[tokio::test]
async fn vless_xhttp_end_to_end() {
    run_variant(
        "xhttp",
        "xhttp",
        "&path=%2Fit-sp&mode=auto",
        json!({ "xhttpSettings": { "path": "/it-sp", "mode": "auto" } }),
    )
    .await;
}

#[tokio::test]
async fn engine_rejects_invalid_config() {
    let Some(bin) = xray_bin() else {
        eprintln!("XRAY_BIN not set: skipping engine validation test");
        return;
    };
    let dir = tempfile::tempdir().unwrap();
    let bad = write_config(
        dir.path(),
        "bad.json",
        &json!({
            "inbounds": [{ "port": 0, "protocol": "nonsense-protocol" }],
            "outbounds": []
        }),
    )
    .await;
    let err = validate_config(&bin, &bad).await.unwrap_err();
    assert!(
        matches!(err, kvn_engine::EngineError::ConfigRejected(_)),
        "expected ConfigRejected, got {err:?}"
    );
}
